+		if (!trimmed) continue;
+		const [sha, shortSha, subject, relativeDate] = trimmed.split("\x1f");
+		if (!sha || !shortSha) continue;
+		commits.push({
+			sha,
+			shortSha,
+			subject: subject ?? "",
+			relativeDate: relativeDate ?? "",
