+function statusFromCode(code: string): SourceControlStatus {
+	switch (code) {
+		case "A":
+		case "C":
+			return "A";
+		case "D":
+			return "D";
+		case "R":
+			return "R";
+		case "U":
+			return "U";
+		default:
+			return "M";
+	}
